import { useState } from 'react';
import type { AdminUserKycResponse, AdminUserKycSession } from '../../../types/adminUser';
import { formatDateTime } from './helpers';

const KYC_OVERRIDE_OPTIONS = [
  { value: 'none', label: 'None (reset)' },
  { value: 'verified', label: 'Verified' },
  { value: 'failed', label: 'Failed' },
];

export interface KycTabProps {
  kycData: AdminUserKycResponse | null;
  /** KYC status from the AdminUser object (faster-loading summary) */
  userKycStatus?: string;
  userKycVerifiedAt?: string;
  userKycExpiresAt?: string;
  error: string | null;
  onRetry: () => void;
  onOverride: (status: string) => Promise<void>;
}

export function KycTab({
  kycData,
  userKycStatus,
  userKycVerifiedAt,
  userKycExpiresAt,
  error,
  onRetry,
  onOverride,
}: KycTabProps) {
  const [overrideStatus, setOverrideStatus] = useState('none');
  const [overrideInProgress, setOverrideInProgress] = useState(false);
  const [overrideError, setOverrideError] = useState<string | null>(null);

  const effectiveStatus = kycData?.status ?? userKycStatus ?? 'none';
  const effectiveVerifiedAt = kycData?.verifiedAt ?? userKycVerifiedAt;
  const effectiveExpiresAt = kycData?.expiresAt ?? userKycExpiresAt;

  const handleOverride = async () => {
    const confirmed = window.confirm(
      `Override KYC status to "${overrideStatus}" for this user?`
    );
    if (!confirmed) return;
    setOverrideInProgress(true);
    setOverrideError(null);
    try {
      await onOverride(overrideStatus);
    } catch (err) {
      setOverrideError(err instanceof Error ? err.message : 'Override failed');
    } finally {
      setOverrideInProgress(false);
    }
  };

  if (error) {
    return (
      <div className="cedros-admin-tab-error">
        <p className="cedros-admin-error-inline">{error}</p>
        <button
          type="button"
          className="cedros-button cedros-button-outline cedros-button-sm"
          onClick={onRetry}
        >
          Retry
        </button>
      </div>
    );
  }

  if (!kycData && !userKycStatus) {
    return (
      <div className="cedros-admin-tab-loading">
        <span className="cedros-admin-loading-indicator" />
        <span>Loading KYC data...</span>
      </div>
    );
  }

  return (
    <div className="cedros-kyc-admin-tab">
      {/* Status summary */}
      <div className="cedros-kyc-admin-tab-summary">
        <div className="cedros-kyc-admin-tab-row">
          <span className="cedros-kyc-admin-tab-label">Status</span>
          <span className={`cedros-admin-status-badge cedros-kyc-status-${effectiveStatus}`}>
            {effectiveStatus}
          </span>
        </div>
        {effectiveVerifiedAt && (
          <div className="cedros-kyc-admin-tab-row">
            <span className="cedros-kyc-admin-tab-label">Verified at</span>
            <span>{formatDateTime(effectiveVerifiedAt)}</span>
          </div>
        )}
        {effectiveExpiresAt && (
          <div className="cedros-kyc-admin-tab-row">
            <span className="cedros-kyc-admin-tab-label">Expires at</span>
            <span>{formatDateTime(effectiveExpiresAt)}</span>
          </div>
        )}
      </div>

      {/* Override */}
      <div className="cedros-kyc-admin-override">
        <span className="cedros-kyc-admin-override-label">Override status</span>
        <select
          className="cedros-kyc-admin-override-select"
          value={overrideStatus}
          onChange={(e) => setOverrideStatus(e.target.value)}
          disabled={overrideInProgress}
          aria-label="Select KYC override status"
        >
          {KYC_OVERRIDE_OPTIONS.map((opt) => (
            <option key={opt.value} value={opt.value}>
              {opt.label}
            </option>
          ))}
        </select>
        <button
          type="button"
          className="cedros-button cedros-button-outline cedros-button-sm"
          onClick={handleOverride}
          disabled={overrideInProgress}
        >
          {overrideInProgress ? 'Saving...' : 'Apply Override'}
        </button>
        {overrideError && <p className="cedros-admin-error-inline">{overrideError}</p>}
      </div>

      {/* Session history */}
      {kycData && kycData.sessions.length > 0 ? (
        <div className="cedros-admin-list-table">
          <div className="cedros-admin-list-thead">
            <div className="cedros-admin-list-th">Date</div>
            <div className="cedros-admin-list-th">Provider</div>
            <div className="cedros-admin-list-th">Status</div>
            <div className="cedros-admin-list-th">Error</div>
            <div className="cedros-admin-list-th">Completed</div>
          </div>
          {kycData.sessions.map((session: AdminUserKycSession) => (
            <div key={session.id} className="cedros-admin-list-row">
              <div className="cedros-admin-list-td">{formatDateTime(session.createdAt)}</div>
              <div className="cedros-admin-list-td">{session.provider}</div>
              <div className="cedros-admin-list-td">
                <span
                  className={`cedros-admin-status-badge cedros-kyc-status-${session.status}`}
                >
                  {session.status}
                </span>
              </div>
              <div className="cedros-admin-list-td cedros-admin-list-td-muted">
                {session.errorCode
                  ? `${session.errorCode}${session.errorReason ? `: ${session.errorReason}` : ''}`
                  : '—'}
              </div>
              <div className="cedros-admin-list-td">
                {session.completedAt ? formatDateTime(session.completedAt) : '—'}
              </div>
            </div>
          ))}
        </div>
      ) : (
        kycData && (
          <div className="cedros-admin-empty-message">No verification sessions found.</div>
        )
      )}
    </div>
  );
}
