/**
 * Presentational panels for AdminUserDetail.
 * UserInfoPanel, CreditStatsPanel, and UserDetailTabs are pure display components.
 */

import type {
  AdminUser,
  AdminUserCreditsResponse,
  AdminUserChatsResponse,
  AdminReferredUsersResponse,
} from '../../../types';
import type { AdminDepositListResponse } from '../../../types/deposit';
import type { AdminUserKycResponse } from '../../../types/adminUser';
import type { AdminUserAccreditationResponse } from '../../../types/accreditation';
import { formatDate, formatCredits } from './helpers';
import { DepositsTab, TransactionsTab, ChatsTab, ReferralsTab } from './tabs';
import { KycTab } from './KycTab';
import { AccreditationTab } from './AccreditationTab';

// =============================================================================
// UserInfoPanel
// =============================================================================

export interface UserInfoPanelProps {
  user: AdminUser;
  isCurrentUser: boolean;
}

export function UserInfoPanel({ user, isCurrentUser }: UserInfoPanelProps) {
  return (
    <div className="cedros-admin-user-detail-info">
      <div className="cedros-admin-user-detail-avatar">
        {user.picture ? (
          <img
            src={user.picture}
            alt={user.name || user.email || 'User'}
            className="cedros-admin-user-detail-avatar-img"
            referrerPolicy="no-referrer"
          />
        ) : (
          <span className="cedros-admin-user-detail-avatar-placeholder">
            {(user.name?.[0] || user.email?.[0] || '?').toUpperCase()}
          </span>
        )}
      </div>
      <div className="cedros-admin-user-detail-meta">
        <h2 className="cedros-admin-user-detail-name">
          {user.name || 'Unknown'}
          {isCurrentUser && <span className="cedros-admin-user-you">(you)</span>}
        </h2>
        <p className="cedros-admin-user-detail-email">
          {user.email || 'No email'}
          {user.emailVerified && (
            <span className="cedros-admin-verified-badge" title="Email verified">
              Verified
            </span>
          )}
        </p>
        {user.isSystemAdmin && (
          <div className="cedros-admin-user-detail-badges">
            <span className="cedros-admin-admin-badge cedros-admin-admin-badge-yes">
              System Admin
            </span>
          </div>
        )}
        <div className="cedros-admin-user-detail-methods">
          <span className="cedros-admin-user-detail-methods-label">Auth Methods:</span>
          {user.authMethods.length > 0 ? (
            user.authMethods.map((method) => (
              <span
                key={method}
                className={`cedros-admin-auth-badge cedros-admin-auth-badge-${method}`}
              >
                {method}
              </span>
            ))
          ) : (
            <span className="cedros-admin-auth-badge cedros-admin-auth-badge-none">none</span>
          )}
        </div>
        <p className="cedros-admin-user-detail-dates">
          Registered: {formatDate(user.createdAt)} | Updated: {formatDate(user.updatedAt)}
        </p>
        {user.referralCode && (
          <div className="cedros-admin-user-detail-referral">
            <span className="cedros-admin-user-detail-referral-label">Referral:</span>
            <span className="cedros-admin-user-detail-referral-code">{user.referralCode}</span>
            {user.referralCount !== undefined && user.referralCount > 0 && (
              <span className="cedros-admin-user-detail-referral-count">
                ({user.referralCount} referred)
              </span>
            )}
            {user.referredBy && (
              <span className="cedros-admin-user-detail-referred-by">
                Referred by:{' '}
                <button
                  type="button"
                  className="cedros-admin-user-uuid-link"
                  onClick={() => navigator.clipboard?.writeText(user.referredBy!)}
                  title="Click to copy referrer UUID"
                >
                  {user.referredBy}
                </button>
              </span>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

// =============================================================================
// CreditStatsPanel
// =============================================================================

export interface CreditStatsPanelProps {
  credits: AdminUserCreditsResponse | null;
  creditsError: string | null;
  onRetry: () => void;
}

export function CreditStatsPanel({ credits, creditsError, onRetry }: CreditStatsPanelProps) {
  if (creditsError) {
    return (
      <div className="cedros-admin-stats-error">
        <p className="cedros-admin-error-inline">{creditsError}</p>
        <button
          type="button"
          className="cedros-button cedros-button-outline cedros-button-sm"
          onClick={onRetry}
        >
          Retry
        </button>
      </div>
    );
  }

  if (!credits) {
    return (
      <div className="cedros-admin-stats-loading">
        <span className="cedros-admin-loading-indicator" />
        <span>Loading credit stats...</span>
      </div>
    );
  }

  return (
    <div className="cedros-admin-user-detail-stats">
      <div className="cedros-admin-stat-card">
        <span className="cedros-admin-stat-label">Credit Balance</span>
        <span className="cedros-admin-stat-value">
          {formatCredits(credits.stats.currentBalanceLamports)}
        </span>
      </div>
      <div className="cedros-admin-stat-card">
        <span className="cedros-admin-stat-label">Total Credited</span>
        <span className="cedros-admin-stat-value">
          {formatCredits(credits.stats.totalDepositedLamports)}
        </span>
      </div>
      <div className="cedros-admin-stat-card">
        <span className="cedros-admin-stat-label">Total Spent</span>
        <span className="cedros-admin-stat-value">
          {formatCredits(credits.stats.totalSpentLamports)}
        </span>
      </div>
      <div className="cedros-admin-stat-card">
        <span className="cedros-admin-stat-label">Deposits</span>
        <span className="cedros-admin-stat-value">{credits.stats.depositCount}</span>
      </div>
      <div className="cedros-admin-stat-card">
        <span className="cedros-admin-stat-label">Transactions</span>
        <span className="cedros-admin-stat-value">{credits.stats.spendCount}</span>
      </div>
    </div>
  );
}

// =============================================================================
// UserDetailTabs — tab bar + tab content switcher
// =============================================================================

export type TabId = 'deposits' | 'transactions' | 'chats' | 'referrals' | 'kyc' | 'accreditation';

export interface UserDetailTabsProps {
  activeTab: TabId;
  onTabChange: (tab: TabId) => void;
  cedrosPayEnabled: boolean;
  user: AdminUser;
  // Data
  deposits: AdminDepositListResponse | null;
  credits: AdminUserCreditsResponse | null;
  chats: AdminUserChatsResponse | null;
  referrals: AdminReferredUsersResponse | null;
  kycData: AdminUserKycResponse | null;
  accreditationData: AdminUserAccreditationResponse | null;
  // Errors
  depositsError: string | null;
  creditsError: string | null;
  chatsError: string | null;
  referralsError: string | null;
  kycError: string | null;
  accreditationError: string | null;
  // Pagination
  depositsCurrentPage: number;
  depositsTotalPages: number;
  onDepositsPageChange: (page: number) => void;
  transactionsCurrentPage: number;
  transactionsTotalPages: number;
  onTransactionsPageChange: (page: number) => void;
  chatsCurrentPage: number;
  chatsTotalPages: number;
  onChatsPageChange: (page: number) => void;
  referralsCurrentPage: number;
  referralsTotalPages: number;
  onReferralsPageChange: (page: number) => void;
  // Loading
  isLoading: boolean;
  // Retry callbacks
  onRetryDeposits: () => void;
  onRetryCredits: () => void;
  onRetryChats: () => void;
  onRetryReferrals: () => void;
  onRetryKyc: () => void;
  onRetryAccreditation: () => void;
  // KYC / accreditation actions
  onKycOverride: (status: string) => Promise<void>;
  onAccreditationOverride: (status: string) => Promise<void>;
  onAccreditationReview: (
    submissionId: string,
    approved: boolean,
    reviewerNotes?: string,
    rejectionReason?: string
  ) => Promise<void>;
}

export function UserDetailTabs({
  activeTab,
  onTabChange,
  cedrosPayEnabled,
  user,
  deposits,
  credits,
  chats,
  referrals,
  kycData,
  accreditationData,
  depositsError,
  creditsError,
  chatsError,
  referralsError,
  kycError,
  accreditationError,
  depositsCurrentPage,
  depositsTotalPages,
  onDepositsPageChange,
  transactionsCurrentPage,
  transactionsTotalPages,
  onTransactionsPageChange,
  chatsCurrentPage,
  chatsTotalPages,
  onChatsPageChange,
  referralsCurrentPage,
  referralsTotalPages,
  onReferralsPageChange,
  isLoading,
  onRetryDeposits,
  onRetryCredits,
  onRetryChats,
  onRetryReferrals,
  onRetryKyc,
  onRetryAccreditation,
  onKycOverride,
  onAccreditationOverride,
  onAccreditationReview,
}: UserDetailTabsProps) {
  return (
    <>
      <div className="cedros-admin-user-detail-tabs">
        <button
          type="button"
          className={`cedros-admin-tab ${activeTab === 'deposits' ? 'cedros-admin-tab-active' : ''}`}
          onClick={() => onTabChange('deposits')}
        >
          Deposits ({deposits?.total ?? 0})
        </button>
        <button
          type="button"
          className={`cedros-admin-tab ${activeTab === 'transactions' ? 'cedros-admin-tab-active' : ''}`}
          onClick={() => onTabChange('transactions')}
        >
          Credits ({credits?.totalTransactions ?? 0})
        </button>
        {cedrosPayEnabled && (
          <button
            type="button"
            className={`cedros-admin-tab ${activeTab === 'chats' ? 'cedros-admin-tab-active' : ''}`}
            onClick={() => onTabChange('chats')}
          >
            Chats ({chats?.total ?? 0})
          </button>
        )}
        <button
          type="button"
          className={`cedros-admin-tab ${activeTab === 'referrals' ? 'cedros-admin-tab-active' : ''}`}
          onClick={() => onTabChange('referrals')}
        >
          Referrals ({referrals?.total ?? user.referralCount ?? 0})
        </button>
        <button
          type="button"
          className={`cedros-admin-tab ${activeTab === 'kyc' ? 'cedros-admin-tab-active' : ''}`}
          onClick={() => onTabChange('kyc')}
        >
          KYC ({kycData?.totalSessions ?? 0})
        </button>
        <button
          type="button"
          className={`cedros-admin-tab ${activeTab === 'accreditation' ? 'cedros-admin-tab-active' : ''}`}
          onClick={() => onTabChange('accreditation')}
        >
          Accreditation ({accreditationData?.totalSubmissions ?? 0})
        </button>
      </div>

      <div className="cedros-admin-user-detail-content">
        {activeTab === 'deposits' && (
          <DepositsTab
            deposits={deposits?.deposits ?? []}
            total={deposits?.total ?? 0}
            currentPage={depositsCurrentPage}
            totalPages={depositsTotalPages}
            onPageChange={onDepositsPageChange}
            isLoading={isLoading}
            error={depositsError}
            onRetry={onRetryDeposits}
          />
        )}
        {activeTab === 'transactions' && (
          <TransactionsTab
            transactions={credits?.transactions ?? []}
            total={credits?.totalTransactions ?? 0}
            currentPage={transactionsCurrentPage}
            totalPages={transactionsTotalPages}
            onPageChange={onTransactionsPageChange}
            error={creditsError}
            onRetry={onRetryCredits}
            isLoading={isLoading}
          />
        )}
        {activeTab === 'chats' && cedrosPayEnabled && (
          <ChatsTab
            sessions={chats?.sessions ?? []}
            total={chats?.total ?? 0}
            currentPage={chatsCurrentPage}
            totalPages={chatsTotalPages}
            onPageChange={onChatsPageChange}
            error={chatsError}
            onRetry={onRetryChats}
            isLoading={isLoading}
          />
        )}
        {activeTab === 'referrals' && (
          <ReferralsTab
            referrals={referrals?.users ?? []}
            total={referrals?.total ?? 0}
            currentPage={referralsCurrentPage}
            totalPages={referralsTotalPages}
            onPageChange={onReferralsPageChange}
            error={referralsError}
            onRetry={onRetryReferrals}
            isLoading={isLoading}
          />
        )}
        {activeTab === 'kyc' && (
          <KycTab
            kycData={kycData}
            userKycStatus={user.kycStatus}
            userKycVerifiedAt={user.kycVerifiedAt}
            userKycExpiresAt={user.kycExpiresAt}
            error={kycError}
            onRetry={onRetryKyc}
            onOverride={onKycOverride}
          />
        )}
        {activeTab === 'accreditation' && (
          <AccreditationTab
            accreditationData={accreditationData}
            userAccreditationStatus={user.accreditationStatus}
            userAccreditationVerifiedAt={user.accreditationVerifiedAt}
            userAccreditationExpiresAt={user.accreditationExpiresAt}
            error={accreditationError}
            onRetry={onRetryAccreditation}
            onOverride={onAccreditationOverride}
            onReview={onAccreditationReview}
          />
        )}
      </div>
    </>
  );
}
