import { useState, useCallback, useMemo } from 'react';
import { AdminUserApiClient } from '../utils/adminUserApi';
import { useCedrosLoginAdminClientContext } from './useCedrosLoginAdminClientContext';
import type {
  AdminReferredUsersResponse,
  AdminUser,
  AdminUserChatsResponse,
  AdminUserCreditsResponse,
  AdminUserStatsResponse,
  ListAdminUsersResponse,
  ListUsersParams,
  UpdateUserRequest,
  UseAdminUsersReturn,
} from '../types';
import type {
  AdminDepositListResponse,
  AdminUserWithdrawalHistoryResponse,
} from '../types/deposit';

/**
 * Hook for admin user management operations
 *
 * Provides methods to list all users, get individual users,
 * and manage system admin status. Requires system admin privileges.
 *
 * @example
 * ```tsx
 * function UserManagement() {
 *   const { users, total, isLoading, listUsers, setSystemAdmin } = useAdminUsers();
 *
 *   useEffect(() => {
 *     listUsers({ limit: 20 });
 *   }, [listUsers]);
 *
 *   return (
 *     <AdminUserList
 *       users={users}
 *       total={total}
 *       isLoading={isLoading}
 *       onToggleAdmin={(userId, isAdmin) => setSystemAdmin(userId, isAdmin)}
 *     />
 *   );
 * }
 * ```
 */
export function useAdminUsers(): UseAdminUsersReturn {
  const { config, _internal } = useCedrosLoginAdminClientContext();

  const [users, setUsers] = useState<AdminUser[]>([]);
  const [total, setTotal] = useState(0);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<Error | null>(null);
  const [lastParams, setLastParams] = useState<ListUsersParams>({});

  const apiClient = useMemo(
    () =>
      new AdminUserApiClient(
        config.serverUrl,
        config.requestTimeout,
        config.retryAttempts,
        _internal?.getAccessToken
      ),
    [config.serverUrl, config.requestTimeout, config.retryAttempts, _internal]
  );

  const listUsers = useCallback(
    async (params?: ListUsersParams): Promise<ListAdminUsersResponse> => {
      setIsLoading(true);
      setError(null);
      setLastParams(params || {});

      try {
        const response = await apiClient.listUsers(params);
        setUsers(response.users);
        setTotal(response.total);
        return response;
      } catch (err) {
        const error = err instanceof Error ? err : new Error('Failed to list users');
        setError(error);
        throw error;
      } finally {
        setIsLoading(false);
      }
    },
    [apiClient]
  );

  const getUser = useCallback(
    async (userId: string): Promise<AdminUser> => {
      setIsLoading(true);
      setError(null);

      try {
        return await apiClient.getUser(userId);
      } catch (err) {
        const error = err instanceof Error ? err : new Error('Failed to get user');
        setError(error);
        throw error;
      } finally {
        setIsLoading(false);
      }
    },
    [apiClient]
  );

  const setSystemAdmin = useCallback(
    async (userId: string, isAdmin: boolean): Promise<void> => {
      setIsLoading(true);
      setError(null);

      try {
        await apiClient.setSystemAdmin(userId, isAdmin);
        // Update local state
        setUsers((prev) =>
          prev.map((user) => (user.id === userId ? { ...user, isSystemAdmin: isAdmin } : user))
        );
      } catch (err) {
        const error = err instanceof Error ? err : new Error('Failed to update admin status');
        setError(error);
        throw error;
      } finally {
        setIsLoading(false);
      }
    },
    [apiClient]
  );

  const updateUser = useCallback(
    async (userId: string, data: UpdateUserRequest): Promise<AdminUser> => {
      setIsLoading(true);
      setError(null);

      try {
        const updated = await apiClient.updateUser(userId, data);
        // Update local state
        setUsers((prev) => prev.map((user) => (user.id === userId ? updated : user)));
        return updated;
      } catch (err) {
        const error = err instanceof Error ? err : new Error('Failed to update user');
        setError(error);
        throw error;
      } finally {
        setIsLoading(false);
      }
    },
    [apiClient]
  );

  const deleteUser = useCallback(
    async (userId: string): Promise<void> => {
      setIsLoading(true);
      setError(null);

      try {
        await apiClient.deleteUser(userId);
        // Remove from local state
        setUsers((prev) => prev.filter((user) => user.id !== userId));
        setTotal((prev) => prev - 1);
      } catch (err) {
        const error = err instanceof Error ? err : new Error('Failed to delete user');
        setError(error);
        throw error;
      } finally {
        setIsLoading(false);
      }
    },
    [apiClient]
  );

  const forcePasswordReset = useCallback(
    async (userId: string): Promise<void> => {
      setIsLoading(true);
      setError(null);

      try {
        await apiClient.forcePasswordReset(userId);
      } catch (err) {
        const error = err instanceof Error ? err : new Error('Failed to send password reset');
        setError(error);
        throw error;
      } finally {
        setIsLoading(false);
      }
    },
    [apiClient]
  );

  const adjustCredits = useCallback(
    async (userId: string, amount: number, reason: string): Promise<void> => {
      setIsLoading(true);
      setError(null);

      try {
        await apiClient.adjustCredits(userId, { amount, reason });
      } catch (err) {
        const error = err instanceof Error ? err : new Error('Failed to adjust credits');
        setError(error);
        throw error;
      } finally {
        setIsLoading(false);
      }
    },
    [apiClient]
  );

  const getUserDeposits = useCallback(
    async (userId: string, params?: ListUsersParams): Promise<AdminDepositListResponse> => {
      setIsLoading(true);
      setError(null);

      try {
        return await apiClient.getUserDeposits(userId, params);
      } catch (err) {
        const error = err instanceof Error ? err : new Error('Failed to get user deposits');
        setError(error);
        throw error;
      } finally {
        setIsLoading(false);
      }
    },
    [apiClient]
  );

  const getUserCredits = useCallback(
    async (userId: string, params?: ListUsersParams): Promise<AdminUserCreditsResponse> => {
      setIsLoading(true);
      setError(null);

      try {
        return await apiClient.getUserCredits(userId, params);
      } catch (err) {
        const error = err instanceof Error ? err : new Error('Failed to get user credits');
        setError(error);
        throw error;
      } finally {
        setIsLoading(false);
      }
    },
    [apiClient]
  );

  const getUserWithdrawalHistory = useCallback(
    async (
      userId: string,
      params?: ListUsersParams
    ): Promise<AdminUserWithdrawalHistoryResponse> => {
      setIsLoading(true);
      setError(null);

      try {
        return await apiClient.getUserWithdrawalHistory(userId, params);
      } catch (err) {
        const error =
          err instanceof Error ? err : new Error('Failed to get user withdrawal history');
        setError(error);
        throw error;
      } finally {
        setIsLoading(false);
      }
    },
    [apiClient]
  );

  const getUserChats = useCallback(
    async (userId: string, params?: ListUsersParams): Promise<AdminUserChatsResponse> => {
      setIsLoading(true);
      setError(null);

      try {
        return await apiClient.getUserChats(userId, params);
      } catch (err) {
        const error = err instanceof Error ? err : new Error('Failed to get user chat history');
        setError(error);
        throw error;
      } finally {
        setIsLoading(false);
      }
    },
    [apiClient]
  );

  const getUserReferrals = useCallback(
    async (userId: string, params?: ListUsersParams): Promise<AdminReferredUsersResponse> => {
      setIsLoading(true);
      setError(null);

      try {
        return await apiClient.getUserReferrals(userId, params);
      } catch (err) {
        const error = err instanceof Error ? err : new Error('Failed to get user referrals');
        setError(error);
        throw error;
      } finally {
        setIsLoading(false);
      }
    },
    [apiClient]
  );

  const getStats = useCallback(async (): Promise<AdminUserStatsResponse> => {
    setIsLoading(true);
    setError(null);

    try {
      return await apiClient.getStats();
    } catch (err) {
      const error = err instanceof Error ? err : new Error('Failed to get user stats');
      setError(error);
      throw error;
    } finally {
      setIsLoading(false);
    }
  }, [apiClient]);

  const refresh = useCallback(async () => {
    await listUsers(lastParams);
  }, [listUsers, lastParams]);

  const clearError = useCallback(() => {
    setError(null);
  }, []);

  return {
    users,
    total,
    isLoading,
    error,
    listUsers,
    getUser,
    setSystemAdmin,
    updateUser,
    deleteUser,
    forcePasswordReset,
    adjustCredits,
    getUserDeposits,
    getUserCredits,
    getUserWithdrawalHistory,
    getUserChats,
    getUserReferrals,
    getStats,
    refresh,
    clearError,
  };
}
