/**
 * Simple tab components for AdminUserDetail.
 * Deposits, Transactions, Chats, Referrals, and Pagination.
 */

import type {
  AdminChatSession,
  AdminCreditTransactionItem,
  ReferredUserItem,
} from '../../../types';
import type { AdminDepositItem } from '../../../types/deposit';
import {
  formatDate,
  formatDateTime,
  formatSol,
  formatCredits,
  formatTxType,
  formatTxDescription,
} from './helpers';

// =============================================================================
// Pagination
// =============================================================================

export interface PaginationProps {
  currentPage: number;
  totalPages: number;
  total: number;
  onPageChange: (page: number) => void;
}

export function Pagination({ currentPage, totalPages, total, onPageChange }: PaginationProps) {
  return (
    <div className="cedros-admin-pagination">
      <button
        type="button"
        className="cedros-button cedros-button-outline cedros-button-sm"
        onClick={() => onPageChange(currentPage - 1)}
        disabled={currentPage <= 1}
      >
        Previous
      </button>
      <span className="cedros-admin-page-info">
        Page {currentPage} of {totalPages} ({total} total)
      </span>
      <button
        type="button"
        className="cedros-button cedros-button-outline cedros-button-sm"
        onClick={() => onPageChange(currentPage + 1)}
        disabled={currentPage >= totalPages}
      >
        Next
      </button>
    </div>
  );
}

// =============================================================================
// Deposits tab
// =============================================================================

export interface DepositsTabProps {
  deposits: AdminDepositItem[];
  total: number;
  currentPage: number;
  totalPages: number;
  onPageChange: (page: number) => void;
  isLoading: boolean;
  error: string | null;
  onRetry: () => void;
}

export function DepositsTab({
  deposits,
  total,
  currentPage,
  totalPages,
  onPageChange,
  isLoading,
  error,
  onRetry,
}: DepositsTabProps) {
  if (error) {
    return (
      <div className="cedros-admin-tab-error">
        <p className="cedros-admin-error-inline">{error}</p>
        <button
          type="button"
          className="cedros-button cedros-button-outline cedros-button-sm"
          onClick={onRetry}
        >
          Retry
        </button>
      </div>
    );
  }

  if (isLoading && deposits.length === 0) {
    return (
      <div className="cedros-admin-tab-loading">
        <span className="cedros-admin-loading-indicator" />
        <span>Loading deposits...</span>
      </div>
    );
  }

  if (total === 0) {
    return <div className="cedros-admin-empty-message">No deposits found.</div>;
  }

  return (
    <>
      <div className="cedros-admin-list-table">
        <div className="cedros-admin-list-thead">
          <div className="cedros-admin-list-th">Date</div>
          <div className="cedros-admin-list-th">Amount</div>
          <div className="cedros-admin-list-th">Status</div>
          <div className="cedros-admin-list-th">Transaction</div>
        </div>
        {deposits.map((deposit) => (
          <div key={deposit.id} className="cedros-admin-list-row">
            <div className="cedros-admin-list-td">{formatDateTime(deposit.createdAt)}</div>
            <div className="cedros-admin-list-td">{formatSol(deposit.amountLamports)}</div>
            <div className="cedros-admin-list-td">
              <span className={`cedros-admin-status-badge cedros-admin-status-${deposit.status}`}>
                {deposit.status}
              </span>
            </div>
            <div className="cedros-admin-list-td cedros-admin-list-td-actions">
              {deposit.txSignature ? (
                <>
                  <span className="cedros-admin-list-td-mono" title={deposit.txSignature}>
                    {deposit.txSignature.slice(0, 8)}...
                  </span>
                  <a
                    href={`https://orbmarkets.io/tx/${deposit.txSignature}`}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="cedros-admin-icon-link"
                    title="View on Orbmarkets"
                    aria-label="View transaction on Orbmarkets"
                  >
                    ↗
                  </a>
                </>
              ) : (
                <span className="cedros-admin-list-td-muted">—</span>
              )}
            </div>
          </div>
        ))}
      </div>
      {totalPages > 1 && (
        <Pagination
          currentPage={currentPage}
          totalPages={totalPages}
          total={total}
          onPageChange={onPageChange}
        />
      )}
    </>
  );
}

// =============================================================================
// Transactions tab
// =============================================================================

export interface TransactionsTabProps {
  transactions: AdminCreditTransactionItem[];
  total: number;
  currentPage: number;
  totalPages: number;
  onPageChange: (page: number) => void;
  isLoading: boolean;
  error: string | null;
  onRetry: () => void;
}

export function TransactionsTab({
  transactions,
  total,
  currentPage,
  totalPages,
  onPageChange,
  isLoading,
  error,
  onRetry,
}: TransactionsTabProps) {
  if (error) {
    return (
      <div className="cedros-admin-tab-error">
        <p className="cedros-admin-error-inline">{error}</p>
        <button
          type="button"
          className="cedros-button cedros-button-outline cedros-button-sm"
          onClick={onRetry}
        >
          Retry
        </button>
      </div>
    );
  }

  if (isLoading && transactions.length === 0) {
    return (
      <div className="cedros-admin-tab-loading">
        <span className="cedros-admin-loading-indicator" />
        <span>Loading transactions...</span>
      </div>
    );
  }

  if (total === 0) {
    return <div className="cedros-admin-empty-message">No credit transactions found.</div>;
  }

  return (
    <>
      <div className="cedros-admin-list-table">
        <div className="cedros-admin-list-thead">
          <div className="cedros-admin-list-th">Date</div>
          <div className="cedros-admin-list-th">Type</div>
          <div className="cedros-admin-list-th">Description</div>
          <div className="cedros-admin-list-th">Amount</div>
        </div>
        {transactions.map((tx) => (
          <div key={tx.id} className="cedros-admin-list-row">
            <div className="cedros-admin-list-td">{formatDateTime(tx.createdAt)}</div>
            <div className="cedros-admin-list-td">
              <span
                className={`cedros-admin-tx-type cedros-admin-tx-type-${tx.txType.toLowerCase()}`}
              >
                {formatTxType(tx.txType)}
              </span>
            </div>
            <div className="cedros-admin-list-td">
              {formatTxDescription(tx.txType, tx.referenceType)}
            </div>
            <div
              className={`cedros-admin-list-td ${tx.amountLamports >= 0 ? 'cedros-admin-amount-positive' : 'cedros-admin-amount-negative'}`}
            >
              {tx.amountLamports >= 0 ? '+' : ''}
              {formatCredits(tx.amountLamports)}
            </div>
          </div>
        ))}
      </div>
      {totalPages > 1 && (
        <Pagination
          currentPage={currentPage}
          totalPages={totalPages}
          total={total}
          onPageChange={onPageChange}
        />
      )}
    </>
  );
}

